use schemars::{JsonSchema, Schema, SchemaGenerator, json_schema, schema_for};
use serde::{Deserialize, Serialize};
use std::borrow::Cow;
use std::str::FromStr;

// ---------- (A) newtype with manual JsonSchema emitting a pattern ----------
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[serde(transparent)]
pub struct Digest(String);

impl FromStr for Digest {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> { Ok(Digest(s.to_owned())) }
}

pub const DIGEST_PATTERN: &str = r"^(sha256|blake3):[a-f0-9]{64}$";

impl JsonSchema for Digest {
    fn schema_name() -> Cow<'static, str> { "Digest".into() }
    fn schema_id() -> Cow<'static, str> { "wisp_contracts::Digest".into() }
    fn inline_schema() -> bool { false }
    fn json_schema(_g: &mut SchemaGenerator) -> Schema {
        json_schema!({
            "type": "string",
            "pattern": DIGEST_PATTERN,
            "title": "Digest",
            "description": "Content digest, `<algo>:<hex>`.",
        })
    }
}

// ---------- (B) derive route: with = String + regex(pattern) on the inner field ----------
#[derive(Serialize, Deserialize, JsonSchema)]
#[serde(transparent)]
pub struct DigestB(#[schemars(regex(pattern = r"^(sha256|blake3):[a-f0-9]{64}$"))] String);

// ---------- (C) derive route: container-level extend ----------
#[derive(Serialize, Deserialize, JsonSchema)]
#[serde(transparent)]
#[schemars(extend("pattern" = r"^(sha256|blake3):[a-f0-9]{64}$"))]
pub struct DigestC(String);

// ---------- (D) non_exhaustive struct + serde derive ----------
/// A doc comment that becomes the description.
#[derive(Serialize, Deserialize, JsonSchema, Debug, Default)]
#[non_exhaustive]
#[serde(rename_all = "snake_case")]
pub struct Wisp {
    pub id: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
}

// ---------- (E) non_exhaustive enum + internal tag + other ----------
#[derive(Serialize, Deserialize, JsonSchema, Debug)]
#[non_exhaustive]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Event {
    Started { at: u64 },
    Finished { at: u64 },
    #[serde(other)]
    Unknown,
}

// ---------- (F) ordered unit enum as string ----------
#[derive(Serialize, Deserialize, JsonSchema, Debug, PartialEq, Eq, PartialOrd, Ord)]
#[serde(rename_all = "snake_case")]
pub enum Severity { Info, Warning, Error }

fn main() {
    let s = schema_for!(Digest);
    println!("A Digest = {}", serde_json::to_string_pretty(&s).unwrap());
    println!("B DigestB = {}", serde_json::to_string(&schema_for!(DigestB)).unwrap());
    println!("C DigestC = {}", serde_json::to_string(&schema_for!(DigestC)).unwrap());
    println!("D Wisp = {}", serde_json::to_string(&schema_for!(Wisp)).unwrap());
    println!("E Event = {}", serde_json::to_string(&schema_for!(Event)).unwrap());
    println!("F Severity = {}", serde_json::to_string(&schema_for!(Severity)).unwrap());

    // non_exhaustive struct deserialize works, unknown fields ignored by default
    let w: Wisp = serde_json::from_str(r#"{"id":"x","note":null,"future_field":42}"#).unwrap();
    println!("D roundtrip: {:?}", w);

    // internally-tagged + other
    let e: Event = serde_json::from_str(r#"{"kind":"exploded","at":1}"#).unwrap();
    println!("E unknown tag -> {:?}", e);

    println!("F ord: {}", Severity::Info < Severity::Error);
    println!("F json: {}", serde_json::to_string(&Severity::Warning).unwrap());
}
